 void OpenPupply(string id,bool hull){popupActions.Clear();popupTitle=hull?"Owned hull supply":"Owned module supply / first family socket";foreach(var item in world.Hangar.Where(i=>i.Value>=1&&(hull?FleetCatalog.ById.GetValueOrDefault(i.Key)?.Playable==true:SupportCatalog.ById.ContainsKey(i.Key)||EwarCatalog.ById.ContainsKey(i.Key)||UtilityCatalog.ById.ContainsKey(i.Key))).Take(16)){string key=item.Key;popupActions.Add((DemoWorld.ItemName(key),()=>NoticeP(hull?world.SupplyHullP(id,key):world.SupplyModuleP(id,key))));}popupRect=new(500,220,600,40+popupActions.Count*29);}
 void SetupCaptureP(){world.NewGame(0);world.SimulationPaused=true;world.WalletFunds=100000;world.EnsurePopulationC();var p=world.Population.Pilots.First(p=>p.Role=="Logi");world.HirePopulationPilotC(p.Id);pilotP=p.Id;world.AssignP(p.Id,"Squad commander",1,1,"Repair");tabP=captureScene switch{"stage-p-homefront"=>1,"stage-p-incursion"=>2,"stage-p-pirate"=>3,"stage-p-regions" or "stage-p-dens"=>4,"stage-p-events"=>5,_=>0};if(tabP==2)world.StartFocusP();if(tabP==5)world.ChoiceP(packP,"Independent");if(tabP is 1 or 2 or 3 or 5){string family=tabP==1?"Homefront":tabP==2?"Incursion":tabP==3?"Pirate":"Event";selectedP=CatalogP.All.First(p=>p.Family==family).Id;world.IssueP(selectedP,tabP==5?packP:"");}if(captureScene=="stage-p-dens"){world.NewExploration43(30003271);world.SimulationPaused=true;world.CargoItems["p_den"]=1;world.DeployDenP();world.SimulationUtc=world.Now.AddHours(2);world.TickP(1);}desktop.Clear();OpenP();}
 int uiChecksP;void RunUiP(int frame){void Check(bool x,string n){if(!x)throw new Exception("P UI FAIL / "+n);uiChecksP++;Console.WriteLine("P UI PASS / "+n);}void Click(string tip){TestClick(ui.Hits.Last(h=>h.Tip==tip).Rect.Center.ToVector2());}if(frame==2){Click("P wing");Check(world.PopulationPilot(pilotP)!.WingP==2,"Hierarchy control persists wing");}if(frame==3){Click("P doctrine / Capacitor");Check(world.PopulationPilot(pilotP)!.DoctrineP=="Capacitor","Doctrine command");}if(frame==4){Click("P broadcast / Hold");Check(world.PopulationPilot(pilotP)!.Order=="Hold","Paid crew broadcast");}if(frame==5){Click("P tab / 1");Check(tabP==1,"Homefront tab");}if(frame==6){Click("P profile / p_10238");Check(selectedP=="p_10238","Source profile selection");}if(frame==7){Click("P request");Check(world.Exploration.Encounters.Any(e=>e.Template==selectedP&&e.RunP!=null),"Costed actual operation");}if(frame==8){Click("P tab / 2");Check(tabP==2,"Incursion tab");}if(frame==9){Click("P focus");Check(world.OperationsP.Focuses.Count==1,"Voluntary regional lifecycle");}if(frame==10){Click("P tab / 3");Check(tabP==3,"Pirate tab");}if(frame==11){Click("P tab / 4");Check(tabP==4,"Regional physical items tab");}if(frame==12){Click("P den buy");Check(world.Hangar.GetValueOrDefault("p_den")==1,"Owned physical kit purchase");}if(frame==13){Click("P tab / 5");Check(tabP==5,"Events tab");}if(frame==14){Click("P choice / Independent");Check(world.OperationsP.Packs[0].Choice=="Independent","Optional independent track");}if(frame==15){Click("P pack");Check(packP=="historical-template-v1","Separate historical replay");Console.WriteLine(uiChecksP+" P UI checks passed.");}}
